import{z as s,x as n,o as e,c as p,q as B,j as o,D as E,d as A,s as t,S as i,b as r}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"高阶套刻","description":"","frontmatter":{"title":"高阶套刻","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/high-order-overlay.md","filePath":"litho/high-order-overlay.md","lastUpdated":1791413859000}'),d={name:"litho/high-order-overlay.md"};function h(D,a,C,m,c,f){const l=n("Mermaid");return e(),p("div",null,[a[2]||(a[2]=B('<h1 id="高阶套刻" tabindex="-1">高阶套刻 <a class="header-anchor" href="#高阶套刻" aria-label="Permalink to &quot;高阶套刻&quot;">​</a></h1><div class="epigraph"><p>平移、旋转、放大只是网格的线性骨架。场内弓形、扫描偏扭与晶圆翘曲的高阶项，要靠够密的标记读数才能看见、才能补。</p><footer>—— 据 ASML 对 overlay 校正与高阶模型的公开论述整理</footer></div><p><a href="/litho/dbo-ibo">上一课</a>把读数选在 IBO 或 DBO 上，并指出加密采样是为了拟合。缺口是模型：扫描机默认能补的线性项吃不掉镜头残差、扫描同步和工艺翘曲的弯曲。本课钉高阶套刻。这些校正由谁在什么时候量、怎么回写到曝光网格，留给<a href="/litho/yieldstar-dbo">下一课</a>的机内计量角色。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对准课已经把网格写成平移、旋转、放大。<a href="/litho/litho-overlay">套刻 Overlay</a> 也提过线性与高阶场内、场间模型。本课补差：产品残差里剩下的空间频率，从哪来、用什么多项式或扫描仪校正项去吃。只报场平均 overlay，等于把弯月形指纹平均成一个看起来合格的点。</p><p><span class="marginnote">直觉类比：只看场平均套刻，就像只看「全班平均分」——平均及格，不代表后排没集体挂科。弯月形指纹在场心近零、四角超标，平均之后这个系统性弯曲就被一个好看的数字藏起来了。</span></p><p>来源包括：投影物镜畸变的高阶、扫描方向的同步与偏扭、工件台与晶圆的热瞬态、薄膜应力翘曲、以及掩模书写指纹。线性项对场心有效时，四角和边场可以已经超标。缺口是场内/场间的阶次，不是再选一次 DBO。项一旦开放，残差图应变平滑而不是变花；变花就是噪声在被拟合。</p><h3 id="采样密度决定看得见的阶" tabindex="-1">采样密度决定看得见的阶 <a class="header-anchor" href="#采样密度决定看得见的阶" aria-label="Permalink to &quot;采样密度决定看得见的阶&quot;">​</a></h3><p>一项 \\(k\\) 阶场内模型，点数少了会欠定或把噪声拟合进去。上一课 DBO 的吞吐优势在这里兑现：同样划片预算下更多点，高阶才可识别。点再多，若全在槽边上，芯片内仍有未建模残差——加密的是槽，不是有源区。</p><p><span class="marginnote">数字实例：一个场内 3 阶多项式在 \\(x\\)、\\(y\\) 两个方向各带约 10 个系数；同一方向的测点若少于系数个数，方程就是欠定的——20 个点硬解 20 个未知数，解出来的是测点噪声而不是真指纹。这就是「阶次跟着点数走」的算术含义。</span></p><p><span class="marginnote">高阶校正补的是曝光时的网格，不是把已刻死的下层搬回来。下层翘曲只能尽量拟合，不能当「无限阶免费套准」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>场间（interfield）：片级网格，描述晶圆平移、旋转、放大、以及径向/弓形的低阶翘曲。场内（intrafield）：每场或每组场的放大、旋转、扫描偏扭、弓形等。ASML 公开材料把这类能力说成 overlay 校正 / 高阶模型 / 与计量闭环，具体产品名随世代变，本课不拿未公开系数表当教材。</p><p>流程：曝光后（或显影后）密采套刻 → 拟合允许的项 → 下一片或本片后续场把校正送回扫描机。过拟合会把计量噪声写成下一场的假指纹，残差看起来更花。项集要按层冻结，换一层薄膜应力，再开放哪些项。</p><p>边场权重要单独看：点数少时高阶项会把边残差「补」到场心去，产品死在边上。</p><h3 id="与线性匹配的分工" tabindex="-1">与线性匹配的分工 <a class="header-anchor" href="#与线性匹配的分工" aria-label="Permalink to &quot;与线性匹配的分工&quot;">​</a></h3><p>混跑匹配套刻首先锁线性：两台机器的放大/旋转一致。高阶匹配更难，因为镜头指纹不同。公开讨论里的 DUV–EUV cross-matching 强调的是产品上残差，不是「高阶项越多越好」。项加到镜头不可重复的那一阶，就是在拟合当天噪声。</p>',17)),(e(),o(i,null,{default:E(()=>[t(l,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20SAMP%5B%22%E5%AF%86%E9%87%87%20DBO%20%2F%20IBO%22%5D%20--%3E%20LIN%5B%22%E7%BA%BF%E6%80%A7%3A%20%E5%B9%B3%E7%A7%BB%20%E6%97%8B%E8%BD%AC%20%E6%94%BE%E5%A4%A7%22%5D%0A%20%20SAMP%20--%3E%20HO%5B%22%E9%AB%98%E9%98%B6%3A%20%E5%BC%93%E5%BD%A2%20%E5%81%8F%E6%89%AD%20%E5%9C%BA%E5%86%85%E5%A4%9A%E9%A1%B9%E5%BC%8F%22%5D%0A%20%20LIN%20--%3E%20GRID%5B%22%E6%9B%9D%E5%85%89%E7%BD%91%E6%A0%BC%22%5D%0A%20%20HO%20--%3E%20GRID%0A%20%20NOISE%5B%22%E8%AE%A1%E9%87%8F%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20HO%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[A("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"扫描投影把「场」沿狭缝积分。扫描方向的速度误差表现为场内 \\(y\\) 相关的套刻；狭缝方向的镜头畸变表现为 \\(x\\) 相关。热载在浸没和 EUV 上都改晶圆与台子的瞬态形状，时间上慢于单场、快于整批，所以校正有本片实时与批次 APC 两档。薄膜应力给出碗状或鞍状，场间高阶吃它；吃不完的部分变成边场系统残差。",-1)),(e(),o(i,null,{default:E(()=>[t(l,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%AE%8B%E5%B7%AE%E7%9A%84%E5%BD%A2%E7%8A%B6%E6%8C%87%E5%90%91%E5%93%AA%E4%B8%AA%E7%89%A9%E7%90%86%E6%BA%90%EF%BC%9F%22%5D%20--%3E%20L%5B%22%E9%95%9C%E5%A4%B4%E7%95%B8%E5%8F%98%EF%BC%9A%E7%8B%AD%E7%BC%9D%E5%90%91%20x%20%E7%9B%B8%E5%85%B3%22%5D%0A%20%20Q%20--%3E%20S%5B%22%E6%89%AB%E6%8F%8F%E9%80%9F%E5%BA%A6%E8%AF%AF%E5%B7%AE%EF%BC%9A%E6%89%AB%E6%8F%8F%E5%90%91%20y%20%E7%9B%B8%E5%85%B3%22%5D%0A%20%20Q%20--%3E%20W%5B%22%E8%96%84%E8%86%9C%E5%BA%94%E5%8A%9B%E7%BF%98%E6%9B%B2%EF%BC%9A%E7%A2%97%E7%8A%B6%20%2F%20%E9%9E%8D%E7%8A%B6%EF%BC%8C%E5%9C%BA%E9%97%B4%22%5D%0A%20%20Q%20--%3E%20M%5B%22%E6%8E%A9%E6%A8%A1%E4%B9%A6%E5%86%99%E6%8C%87%E7%BA%B9%EF%BC%9A%E5%9C%BA%E5%86%85%E4%BD%86%E7%A8%B3%E5%AE%9A%22%5D%0A%20%20L%20--%3E%20LC%5B%22%E5%9C%BA%E5%86%85%E5%A4%9A%E9%A1%B9%E5%BC%8F%E5%90%83%20x%20%E9%A1%B9%22%5D%0A%20%20S%20--%3E%20SC%5B%22%E6%89%AB%E6%8F%8F%E5%90%8C%E6%AD%A5%E6%A0%A1%E6%AD%A3%E5%90%83%20y%20%E9%A1%B9%22%5D%0A%20%20W%20--%3E%20WC%5B%22%E5%9C%BA%E9%97%B4%E7%BD%91%E6%A0%BC%E9%AB%98%E9%98%B6%E5%90%83%E5%BC%AF%E6%9C%88%22%5D%0A%20%20M%20--%3E%20MC%5B%22%E6%8E%A9%E6%A8%A1%E4%B8%93%E7%94%A8%E6%A0%A1%E6%AD%A3%E4%B8%80%E6%AC%A1%E6%90%9E%E5%AE%9A%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p><span class="marginnote">术语翻译：「弓形」就是场内图形的中线沿扫描方向弯成一张弓；「偏扭」是图形随位置被逐渐扭转一个角度。这两种弯曲线性项都看不见，必须用高阶项描述。</span></p><p>LELE 把两次曝光的相对高阶直接写成节距指纹：场四角节距和场心不同。SADP 层内自对准，但切层对鳍的高阶套刻仍在。预算必须按策略拆，不能对所有层开放同一套项。</p><p><span class="marginnote">「高阶 overlay 更好」只在项与物理源对齐、且采样可识别时成立。把多项式阶数当分辨率竞赛，会把噪声写进产品。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不发明 ASML 未公布的残差纳米数，也不把某一代 NXT 的演示 overlay 复制成所有层的高阶能力。计算光刻不直接减小套刻，但图形对套刻的敏感度（切线、孔）决定哪些高阶必须补。标记不对称的系统偏置会被高阶模型当成真指纹——上一课的工艺风，本课的模型会认真地把它补进下一片，方向可能更错。</p><p>后课默认：说到产品套刻控制，已包含线性加受控高阶；计量机必须供得起密度。YieldStar 一类如何挂在扫描机旁边，下一课只讲产品角色。</p><p><span class="marginnote">场内校正与掩模加热补偿不是同一个旋钮。掩模热膨胀有自己的时间尺度，硬塞进晶圆高阶会把空闲时的网格弄脏。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>线性项是骨架；弓形、偏扭与翘曲要高阶项才看得见。</li><li>采样密度和标记位置决定项能否识别，DBO 加密为此服务。</li><li>过拟合把计量噪声写进下一场；项集按层冻结。</li><li>工艺不对称会被模型当真指纹，先收标记再加阶。</li><li>出处：ASML overlay 校正与高阶模型的公开论述；Levinson 对套刻控制的讨论。</li></ul>',9))])}const _=s(d,[["render",h]]);export{F as __pageData,_ as default};
